1	import { useCallback, useEffect, useState } from 'react';
2	import { Arc } from '../components/Arc';
3	import { Sheet } from '../components/Sheet';
4	import { AddSchedule } from './AddSchedule';
5	import { DoseHistory } from './DoseHistory';
6	import { DayDoses } from './DayDoses';
7	import { useAuth } from '../lib/auth';
8	import { usePrefs } from '../lib/prefs';
9	import { ensureTodayDoses, getComplianceMap, getDosesForDate, setDoseTaken, type Dose } from '../lib/api';
10	import { addDays, formatDisplayDate, formatShortDate, parseHour, startOfWeekMonday, toISODate } from '../lib/date';
11	import { useNow } from '../lib/now';
12	import { useActiveTab } from '../lib/activeTab';
13	import { IconCalculator, IconPlus } from '../components/Icons';
14	import { ReconCalculator } from './ReconCalculator';
15	import { DoseRow } from '../components/DoseRow';
16	import { syncScheduleNotifications } from '../lib/notifications';
17	
18	type DayState = 'completed' | 'missed' | 'today' | 'future';
19	
20	function dayState(dateISO: string, todayISO: string, compliance: Record<string, { total: number; taken: number }>): DayState {
21	  if (dateISO === todayISO) return 'today';
22	  if (dateISO > todayISO) return 'future';
23	  const c = compliance[dateISO];
24	  return c && c.total > 0 && c.taken === c.total ? 'completed' : 'missed';
25	}
26	
27	type SheetState =
28	  | { kind: 'add' }
29	  | { kind: 'history'; name: string; scheduleItemId: string | null }
30	  | { kind: 'day'; date: Date }
31	  | { kind: 'calculator' }
32	  | null;
33	
34	export function Today() {
35	  const { user } = useAuth();
36	  const { profile } = usePrefs();
37	  const activeTab = useActiveTab();
38	  const [doses, setDoses] = useState<Dose[] | null>(null);
39	  const [compliance, setCompliance] = useState<Record<string, { total: number; taken: number }>>({});
40	  const [sheet, setSheet] = useState<SheetState>(null);
41	
42	  // live: the header date, the week strip and the arc's "now" all read from
43	  // this, so the screen rolls over at midnight instead of at the next reload
44	  const today = useNow();
45	  const todayISO = toISODate(today);
46	  const weekStart = startOfWeekMonday(today);
47	  const weekDays = Array.from({ length: 7 }, (_, i) => addDays(weekStart, i));
48	
49	  const load = useCallback(async () => {
50	    if (!user) return;
51	    // Materialize today's row for every active schedule item before reading —
52	    // that's the whole trick: the user set the amount up once, this just
53	    // stops asking them to retype it every morning.
54	    await ensureTodayDoses(user.id);
55	    const [d, c] = await Promise.all([
56	      getDosesForDate(user.id, today),
57	      getComplianceMap(user.id, weekStart, addDays(weekStart, 6)),
58	    ]);
59	    setDoses(d);
60	    setCompliance(c);
61	    syncScheduleNotifications(user.id);
62	    // eslint-disable-next-line react-hooks/exhaustive-deps
63	  }, [user?.id, todayISO]);
64	
65	  /* All three screens stay mounted, so adding something to the schedule from
66	     Discover left Today holding the list it fetched once on first mount — the
67	     new item only appeared after the app was reopened, which read as "it went
68	     in for tomorrow". Refetching when Today becomes the active tab is the same
69	     fix the stack already uses; see lib/activeTab. */
70	  useEffect(() => {
71	    if (activeTab === 0) load();
72	  }, [load, activeTab]);
73	
74	  const refreshCompliance = useCallback(async () => {
75	    if (!user) return;
76	    setCompliance(await getComplianceMap(user.id, weekStart, addDays(weekStart, 6)));
77	    // eslint-disable-next-line react-hooks/exhaustive-deps
78	  }, [user?.id]);
79	
80	  const toggleTaken = async (dose: Dose) => {
81	    if (!user) return;
82	    const updated = await setDoseTaken(dose.id, !dose.taken);
83	    setDoses((prev) => (prev ? prev.map((d) => (d.id === dose.id ? updated : d)) : prev));
84	    // taken/not-taken feeds the compliance map too — refresh the week
85	    await refreshCompliance();
86	    /* Deliberately opens nothing. This used to push the history sheet up,
87	       which offered Remove From Schedule as the response to someone simply
88	       marking their supplement as taken. The sheet is a long press now. */
89	  };
90	
91	  if (!user) return null;
92	
93	  const leftToday = doses ? doses.filter((d) => !d.taken).length : 0;
94	  const arcDoses = (doses ?? [])
95	    .map((d) => ({ id: d.id, hour: parseHour(d.scheduled_time), taken: d.taken }))
96	    .filter((d): d is { id: string; hour: number; taken: boolean } => d.hour !== null);
97	
98	  const nowHour = today.getHours() + today.getMinutes() / 60;
99	  const overdue = (doses ?? []).filter((d) => !d.taken && d.scheduled_time && (parseHour(d.scheduled_time) ?? 99) <= nowHour);
100	
101	  return (
102	    <>
103	      <div className="screen-head">
104	        <h1 className="t-title">Today</h1>
105	        <div className="screen-sub t-body">{formatDisplayDate(today)}</div>
106	      </div>
107	
108	      {/* One property means one thing: fill = today, dot = completed. */}
109	      <div className="week">
110	        {weekDays.map((d) => {
111	          const iso = toISODate(d);
112	          const state = dayState(iso, todayISO, compliance);
113	          return (
114	            <div
115	              key={iso}
116	              className={`week-cell ${state} pressable`}
117	              onClick={() => setSheet({ kind: 'day', date: d })}
118	            >
119	              <span className="week-dow">{d.toLocaleDateString(undefined, { weekday: 'narrow' })}</span>
120	              <span className="week-num">{d.getDate()}</span>
121	              {state === 'completed' && <span className="week-dot" />}
122	            </div>
123	          );
124	        })}
125	      </div>
126	
127	      {/* the arc spans the user's own waking day, so the dividers land where
128	          those times actually fall. Defaults until onboarding has set them. */}
129	      <Arc
130	        doses={arcDoses}
131	        leftToday={leftToday}
132	        dayStart={parseHour(profile?.wake_time ?? null) ?? 7}
133	        dayEnd={parseHour(profile?.sleep_time ?? null) ?? 23}
134	      />
135	
136	      <div className="divider">
137	        <span className="divider-line" />
138	        <span className="divider-text t-section">Schedule</span>
139	        <span className="divider-line" />
140	      </div>
141	
142	      <div className="timeline">
143	        <span className="rail" />
144	        {doses === null && <div className="sheet-empty t-body">Loading…</div>}
145	        {doses !== null && doses.length === 0 && (
146	          <div className="empty-state t-body">Nothing on your schedule yet.</div>
147	        )}
148	        {doses?.map((d) => (
149	          <DoseRow
150	            key={d.id}
151	            dose={d}
152	            onToggle={toggleTaken}
153	            onLongPress={(dose) =>
154	              setSheet({ kind: 'history', name: dose.name, scheduleItemId: dose.schedule_item_id })
155	            }
156	          />
157	        ))}
158	      </div>
159	
160	      <div className="action-row">
161	        <button className="add-dose pressable" onClick={() => setSheet({ kind: 'add' })}>
162	          <IconPlus size={15} color="var(--purple)" />
163	          Add to Schedule
164	        </button>
165	        <button className="add-dose pressable" onClick={() => setSheet({ kind: 'calculator' })}>
166	          <IconCalculator size={15} color="var(--purple)" />
167	          Calculator
168	        </button>
169	      </div>
170	
171	      {overdue.length > 0 && (
172	        <button
173	          className="warn"
174	          onClick={() =>
175	            setSheet({ kind: 'history', name: overdue[0].name, scheduleItemId: overdue[0].schedule_item_id })
176	          }
