1	import type { Page, Request } from '@playwright/test';
2	import { SUPABASE_URL } from './env';
3	import { INSERT_DEFAULTS, makeTables, STUB_EMAIL, STUB_USER_ID, type Row } from './catalogue';
4	
5	/**
6	 * A Supabase that never leaves the browser.
7	 *
8	 * Every request the client makes is fulfilled by page.route(), so the tests
9	 * need no project, no keys and no network. It models enough of GoTrue and
10	 * PostgREST for the app's own calls — eq/in/gte/lte filters and `limit`, plus
11	 * the single-object Accept header — and nothing more. Embedded selects
12	 * (`glossary:glossary_id(*)`), `order` and `not.` filters are answered
13	 * unfiltered; no screen under test depends on them.
14	 *
15	 * Anything it does not recognise is recorded in `unhandled` rather than
16	 * guessed at, and the test fixture fails the test if that list is not empty.
17	 * A silent [] for a table nobody modelled is exactly the kind of pass that
18	 * makes a smoke test worthless.
19	 */
20	
21	const PREFIX = new URL(SUPABASE_URL).pathname;
22	const DAY_SECONDS = 86_400;
23	
24	/** Not a credential; the endpoint that would check it is intercepted. */
25	const ACCESS_TOKEN = 'stub-access-token';
26	const REFRESH_TOKEN = 'stub-refresh-token';
27	
28	export function stubUser(): Row {
29	  const now = new Date().toISOString();
30	  return {
31	    id: STUB_USER_ID,
32	    aud: 'authenticated',
33	    role: 'authenticated',
34	    email: STUB_EMAIL,
35	    email_confirmed_at: now,
36	    phone: '',
37	    confirmed_at: now,
38	    last_sign_in_at: now,
39	    app_metadata: { provider: 'email', providers: ['email'] },
40	    user_metadata: { display_name: 'Smoke' },
41	    identities: [],
42	    created_at: now,
43	    updated_at: now,
44	  };
45	}
46	
47	/** Far enough from expiry that the client never tries to refresh mid-test. */
48	export function stubSession(): Row {
49	  return {
50	    access_token: ACCESS_TOKEN,
51	    token_type: 'bearer',
52	    expires_in: DAY_SECONDS,
53	    expires_at: Math.floor(Date.now() / 1000) + DAY_SECONDS,
54	    refresh_token: REFRESH_TOKEN,
55	    user: stubUser(),
56	  };
57	}
58	
59	export interface Stub {
60	  /** Live table contents, so a test can assert on what the app wrote. */
61	  db: Record<string, Row[]>;
62	  /** `METHOD /path` for every call the stub could not model. Empty is passing. */
63	  unhandled: string[];
64	}
65	
66	export async function installSupabaseStub(page: Page): Promise<Stub> {
67	  const stub: Stub = { db: makeTables(), unhandled: [] };
68	  let generated = 0;
69	
70	  await page.route(`${SUPABASE_URL}/**`, async (route) => {
71	    const request = route.request();
72	    const url = new URL(request.url());
73	    const path = url.pathname.slice(PREFIX.length);
74	    const method = request.method();
75	
76	    const miss = (status = 404) => {
77	      stub.unhandled.push(`${method} ${path}`);
78	      return route.fulfill({
79	        status,
80	        contentType: 'application/json',
81	        body: JSON.stringify({ message: `stub has no route for ${method} ${path}` }),
82	      });
83	    };
84	    const json = (body: unknown, status = 200, headers: Record<string, string> = {}) =>
85	      route.fulfill({ status, contentType: 'application/json', headers, body: JSON.stringify(body) });
86	
87	    /* ── GoTrue ───────────────────────────────────────────────────────── */
88	
89	    if (path.startsWith('/auth/v1/')) {
90	      const endpoint = path.slice('/auth/v1/'.length);
91	      if (endpoint === 'signup' || endpoint === 'token') return json(stubSession());
92	      if (endpoint === 'user') return json(stubUser());
93	      if (endpoint === 'logout') return route.fulfill({ status: 204, body: '' });
94	      return miss();
95	    }
96	
97	    /* ── PostgREST ────────────────────────────────────────────────────── */
98	
99	    if (!path.startsWith('/rest/v1/')) return miss();
100	    const relation = path.slice('/rest/v1/'.length);
101	
102	    if (relation.startsWith('rpc/')) {
103	      // match_goal is the only RPC the app calls, and only from the search box.
104	      if (relation === 'rpc/match_goal') {
105	        const { query_text } = (request.postDataJSON() ?? {}) as { query_text?: string };
106	        const q = (query_text ?? '').toLowerCase();
107	        return json(stub.db.glossary.filter((r) => String(r.name).toLowerCase().includes(q)));
108	      }
109	      return miss();
110	    }
111	
112	    const table = stub.db[relation];
113	    if (!table) return miss();
114	
