import { expect, seedSignedIn, test } from './support/app';
import { STUB_USER_ID } from './support/catalogue';

/** TEMPORARY measurement harness — delete before committing. */

const WIDTHS = [375, 390, 430];

function items(times: string[]) {
  return times.map((t, i) => ({
    id: `dddddddd-0000-4000-8000-00000000000${i + 1}`,
    user_id: STUB_USER_ID,
    glossary_id: 'aaaaaaaa-0000-4000-8000-000000000001',
    name: `Scratch ${i + 1}`,
    amount: '1 capsule',
    scheduled_time: t,
    injection_site: null,
    active: true,
    created_at: '2020-01-01T00:00:00.000Z',
    start_date: '2020-01-01',
  }));
}

for (const width of WIDTHS) {
  test.describe(`w${width}`, () => {
    test.use({ viewport: { width, height: 852 } });

    test(`measures the arc at ${width}`, async ({ page, app }) => {
      await seedSignedIn(page, app.stub);
      app.stub.db.schedule_items.push(...items(['06:00:00', '08:00:00', '12:00:00', '18:00:00', '22:00:00', '23:30:00']));
      await page.goto('/');
      await expect(page.getByRole('heading', { name: 'Today' })).toBeVisible();
      await expect(page.locator('.arc-wrap svg path')).not.toHaveCount(0);

      const m = await page.evaluate(() => {
        const svg = document.querySelector('.arc-wrap svg') as SVGSVGElement;
        const panel = svg.closest('.panel') as HTMLElement;
        const paths = [...svg.querySelectorAll('path')];
        const boxes = paths.map((p) => {
          const r = p.getBoundingClientRect();
          return { l: +r.left.toFixed(2), r: +r.right.toFixed(2), t: +r.top.toFixed(2), b: +r.bottom.toFixed(2) };
        });
        const svgR = svg.getBoundingClientRect();
        const panelR = panel.getBoundingClientRect();
        return {
          viewBox: svg.getAttribute('viewBox'),
          attrW: svg.getAttribute('width'),
          attrH: svg.getAttribute('height'),
          svg: { l: +svgR.left.toFixed(2), r: +svgR.right.toFixed(2), t: +svgR.top.toFixed(2), b: +svgR.bottom.toFixed(2) },
          panel: { l: +panelR.left.toFixed(2), r: +panelR.right.toFixed(2) },
          paint: {
            l: +Math.min(...boxes.map((b) => b.l)).toFixed(2),
            r: +Math.max(...boxes.map((b) => b.r)).toFixed(2),
            t: +Math.min(...boxes.map((b) => b.t)).toFixed(2),
            b: +Math.max(...boxes.map((b) => b.b)).toFixed(2),
          },
        };
      });
      console.log(`\n=== ${width} ===\n` + JSON.stringify(m, null, 2));
      await page.locator('.arc-wrap').screenshot({ path: `.scratch/arc-${width}.png` });
      await page.screenshot({ path: `.scratch/today-${width}.png` });
    });
  });
}

