/* ============================================================
   Halfpast — design tokens. Nothing outside this block defines
   a colour. Elevation is opaque steps, never 1px hairlines.
   ============================================================ */
:root {
  --bg: #000000;
  --card: #16161a;
  --card-hi: #1e1e22;
  /* the Discover result card sits one step above --card in the export */
  --card-2: #252529;
  --purple: #7b5cfa;
  --purple-dim: rgba(123, 92, 250, 0.35);

  /* Glass, measured off the exports rather than guessed. The fill is a barely
     there white over black; the read comes almost entirely from the rim, which
     is directional — bright along the top and left, faint along the bottom,
     absent on the right. That is a lit edge, not a uniform hairline. */
  --glass: rgba(255, 255, 255, 0.022);
  --rim-hi: rgba(255, 255, 255, 0.36);
  --rim-lo: rgba(255, 255, 255, 0.07);
  /* The pill reads as translucent purple but cannot be: it is greener-poor
     than the bar underneath, so no alpha over --card reaches it. These are the
     two ends of the gradient the export actually paints. */
  --pill-1: #181130;
  --pill-2: #272042;
  --scrim: rgba(0, 0, 0, 0.55);
  --danger: #ff6b6b;
  --danger-dim: rgba(255, 107, 107, 0.55);
  --pill-rim-hi: rgba(255, 255, 255, 0.4);
  --pill-rim-lo: rgba(255, 255, 255, 0.09);

  --t1: rgba(255, 255, 255, 1);
  --t2: rgba(255, 255, 255, 0.62);
  --t3: rgba(255, 255, 255, 0.38);
  --t4: rgba(255, 255, 255, 0.22);

  /* the arc's unfilled segments — an opaque step, not a white alpha */
  --track: #252528;
  /* the calendar's empty cell */
  --cell-empty: #0e0e11;

  --margin: 20px;
  --tab-h: 48px;

  /* Larger Text multiplies this rather than zooming the layout — zoom
     scales the whole box model (including the fixed 402x874 desktop
     preview frame and its overflow:hidden clip), which pushed real
     content outside the clip and broke hit-testing on real buttons. */
  --text-scale: 1;

  color-scheme: dark;
}
.app.larger-text {
  --text-scale: 1.14;
}

/* One material, used wherever the export shows one. */
.glass {
  background: var(--glass);
  box-shadow:
    inset 1px 1px 0 var(--rim-hi),
    inset -1px -1px 0 var(--rim-lo);
}

/* ── the four tells that scream "website" ── */
* {
  -webkit-tap-highlight-color: transparent;
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--t1);
  overscroll-behavior: none;
  -webkit-user-select: none;
  user-select: none;
  touch-action: manipulation;
  -webkit-font-smoothing: antialiased;
  /* -apple-system resolves to real SF Pro on device — that is most of the
     native read. Inter is only the desktop fallback, never fetched. */
  font-family: -apple-system, 'SF Pro Text', 'SF Pro Display', Inter, system-ui, sans-serif;
}

h1,
h2,
h3,
p {
  margin: 0;
  font-weight: inherit;
}

button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  padding: 0;
  cursor: pointer;
}

/* ============================================================
   Type scale
   ============================================================ */
.t-title {
  font-size: calc(33px * var(--text-scale));
  font-weight: 700;
  letter-spacing: -1px;
  line-height: calc(38px * var(--text-scale));
}
.t-big {
  font-size: calc(44px * var(--text-scale));
  font-weight: 700;
  letter-spacing: -1.5px;
  line-height: 1;
}
.t-section {
  font-size: calc(17px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.45px;
}
.t-body {
  font-size: calc(15px * var(--text-scale));
  font-weight: 400;
  letter-spacing: -0.1px;
}
.t-body-m {
  font-size: calc(15px * var(--text-scale));
  font-weight: 500;
  letter-spacing: -0.1px;
}
.t-secondary {
  font-size: calc(13px * var(--text-scale));
  font-weight: 400;
  letter-spacing: 0;
}
.t-caption {
  font-size: calc(12px * var(--text-scale));
  font-weight: 400;
  letter-spacing: 0;
}
.t-label {
  font-size: calc(10.5px * var(--text-scale));
  font-weight: 600;
  letter-spacing: 1.1px;
  text-transform: uppercase;
}

/* ============================================================
   App shell
   ============================================================ */
.app {
  position: relative;
  width: 100%;
  height: 100dvh; /* never vh — Safari's collapsing toolbar clips the bottom */
  overflow: hidden;
  background: var(--bg);
}

/* Desktop preview only: a phone-shaped box. On a real device the app is
   the viewport and this never applies. */
.frame-host {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  background: var(--card);
}
.frame {
  position: relative;
  width: 402px;
  height: 874px;
  overflow: hidden;
  border-radius: 44px;
  background: var(--bg);
  flex: none;
  /* a transform makes this the containing block for position:fixed
     descendants (the Sheet overlay) — without it, fixed elements anchor
     to the real browser viewport instead of this phone-mockup box. */
  transform: translateZ(0);
}

.status {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 54px;
  padding: 0 var(--margin);
  padding-top: env(safe-area-inset-top);
  display: flex;
  align-items: center;
  z-index: 8;
  pointer-events: none;
}
.status span {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.2px;
}

/* ── the horizontal page controller ── */
.track {
  position: absolute;
  inset: 0;
  display: flex;
  width: 300%;
  will-change: transform;
}
.panel {
  width: 33.3333%;
  height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  padding: 0 var(--margin);
  /* On a device the status bar is the OS's (standalone) or Safari's (browser),
     and the inset already accounts for it. Only the desktop phone-box draws a
     fake one, and only there does the 54px band exist. */
  padding-top: env(safe-area-inset-top);
  padding-bottom: calc(var(--tab-h) + 34px + env(safe-area-inset-bottom));
}
.app.framed .panel {
  padding-top: 54px;
}
.panel::-webkit-scrollbar {
  width: 0;
  height: 0;
}

/* ============================================================
   Press states — a row that does nothing until you lift feels dead
   ============================================================ */
.pressable {
  transition:
    background-color 90ms ease-out,
    transform 90ms ease-out;
}
.pressable:active {
  background-color: var(--card-hi);
  transform: scale(0.985);
}

/* ============================================================
   Tab bar
   ============================================================ */
.bar {
  position: absolute;
  left: 50%;
