}
.pill {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  border-radius: 17px;
  /* glass, lit from the top-left, exactly as the export renders it */
  background: linear-gradient(160deg, var(--pill-1), var(--pill-2));
