.match-context {
  color: var(--t3);
  line-height: 1.4;
}

.result {
  /* the card is inset a further 8px inside the 20px margin */
  margin: 27px 8px 0;
  background: var(--card-2);
  border-radius: 22px;
  padding: 15px 15px 9px;
}
.result-title {
  line-height: calc(18px * var(--text-scale));
  color: var(--purple);
  font-size: calc(15px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.1px;
}
/* placeholder for a paper thumbnail — --card, never white */
.thumb {
  margin-top: 6px;
  height: 215px;
  border-radius: 15px;
  background: var(--card-hi);
  display: grid;
  place-items: center;
}
.result-actions {
  display: flex;
  gap: 10px;
  margin-top: 13px;
}
/* the only row that shares width between two buttons */
.result-actions .btn {
  flex: 1;
  min-width: 0;
}
/* NOT flex: 1. This button is used inside column flex containers (.auth-form,
   the sheets), where flex:1 resolves flex-basis:0 against the VERTICAL axis and
   silently overrides the height — every button in a form collapsed to ~20px.
   The one place it needs to share a row scopes it below. */
.btn {
  flex: none;
  height: 56px;
  min-height: 56px;
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: calc(15px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.1px;
}
.btn-fill {
  background: var(--purple);
  color: #000;
}
.btn-out {
  box-shadow: inset 0 0 0 1.5px var(--purple);
  color: var(--purple);
}

.papers {
  position: relative;
  margin-top: 12px;
  padding-left: 22px;
}
.paper {
  height: 54px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.paper-title {
  line-height: calc(18px * var(--text-scale));
  font-size: calc(15px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.1px;
}
.paper-meta {
  margin-top: 4px;
  line-height: calc(14px * var(--text-scale));
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--t3);
  font-size: calc(12px * var(--text-scale));
}
.paper-add {
  margin-left: auto;
  flex: none;
  width: 22px;
  height: 22px;
  border-radius: 11px;
  background: var(--card-hi);
  color: var(--t2);
  display: grid;
  place-items: center;
}
.paper-add:disabled {
  opacity: 0.7;
}
.paper-more {
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--purple);
  font-size: calc(12px * var(--text-scale));
}

/* ============================================================
   You
   ============================================================ */
.streak {
  margin-top: 8px;
  line-height: calc(20px * var(--text-scale));
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--purple);
  font-size: calc(15px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.1px;
}

.widgets {
  display: flex;
  gap: 12px;
  /* the pair runs 6px wider than the margin on each side in the export */
  margin: 19px -6px 0;
}
.widget {
  width: 181px;
  height: 176px;
  border-radius: 22px;
  background: var(--card);
  flex: none;
  padding: 12px;
  overflow: hidden;
  /* the calendar below takes whatever height is left, rather than assuming
     a row count and spilling past the corner when the month needs six */
  display: flex;
  flex-direction: column;
}
.widget-num {
  text-align: center;
  color: var(--purple);
  font-size: calc(44px * var(--text-scale));
  font-weight: 700;
  letter-spacing: -1.5px;
  line-height: 1;
}
/* One grid: a weekday header row, then one row per week of THIS month.
   --cal-rows comes from the data, and every row is 1fr, so a 4-row February
   and a 6-row month both land inside the widget instead of overflowing it. */
.cal {
  margin-top: 8px;
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: 13px repeat(7, minmax(0, 1fr));
  grid-template-rows: 12px repeat(var(--cal-rows, 5), minmax(0, 1fr));
  gap: 3px 4px;
}
.cal-week-label {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  color: var(--t3);
  font-size: calc(9px * var(--text-scale));
  line-height: 1;
}
.cal-dow {
  text-align: center;
  color: var(--t3);
  font-size: calc(10px * var(--text-scale));
  line-height: 12px;
}
.cal-cell {
  min-height: 0;
  border-radius: 4px;
  background: var(--cell-empty);
}
.cal-cell.on {
  background: var(--purple);
}
/* today reads as an outline, so it stacks with .on rather than fighting it */
.cal-cell.today {
  box-shadow: inset 0 0 0 1.5px var(--purple);
}
/* the days before the 1st and after the last: space, not a square */
.cal-corner,
.cal-blank {
  background: none;
}

/* an intentionally empty box — the label names what belongs here */
.widget-gap {
  display: grid;
  place-items: center;
  text-align: center;
  padding: 18px;
}
.widget-gap span {
  color: var(--t3);
  font-size: calc(12px * var(--text-scale));
  line-height: 1.4;
}

.rows {
  margin-top: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.row {
  display: flex;
  align-items: center;
  height: 48px;
  padding: 0 16px;
  border-radius: 16px;
  background: var(--card);
}
.row-label {
  flex: 1;
  font-size: calc(15px * var(--text-scale));
  font-weight: 500;
  letter-spacing: -0.1px;
}
.row-value {
  color: var(--t3);
  font-size: calc(13px * var(--text-scale));
}

/* ============================================================
   Loading splash
   ============================================================ */
.splash {
  display: flex;
  align-items: center;
  justify-content: center;
}

/* ============================================================
   Auth
   ============================================================ */
.auth-panel {
  /* deliberately not `.panel` — that class is 33.3333% wide, sized for the
     three-way pager inside `.track`; reused bare here it squeezed the whole
     screen into a third of the frame's width. */
  width: 100%;
  height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  padding: 0 var(--margin);
  padding-top: env(safe-area-inset-top);
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding-bottom: env(safe-area-inset-bottom);
}
.app.framed .auth-panel {
  padding-top: 54px;
}
.auth-screen {
  width: 100%;
}
.auth-head {
  margin-bottom: 28px;
}
.auth-form {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}
.field-row {
  display: flex;
  gap: 12px;
}
.stack-pick-row {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 2px;
  -webkit-overflow-scrolling: touch;
}
.stack-pick-row::-webkit-scrollbar {
  display: none;
}
.stack-pick-chip {
  flex: none;
  display: inline-flex;
  align-items: center;
  height: 38px;
  padding: 0 16px;
  border-radius: 15px;
  background: var(--card);
  color: var(--t2);
  font-size: calc(13px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.1px;
  white-space: nowrap;
}
.stack-pick-chip.active {
  background: var(--purple);
  color: var(--bg);
}
.field .t-label {
  color: var(--t3);
}
.field-input {
  min-height: 52px;
  height: 46px;
  border-radius: 14px;
  background: var(--card);
  border: 0;
  outline: none;
  padding: 0 14px;
  color: var(--t1);
  font-size: calc(15px * var(--text-scale));
  letter-spacing: -0.1px;
  font-family: inherit;
  -webkit-user-select: text;
  user-select: text;
}
.field-input::placeholder {
  color: var(--t3);
}
.auth-error {
  color: #ff6b6b;
}
.auth-switch {
  margin-top: 20px;
  text-align: center;
  width: 100%;
  color: var(--t2);
  font-size: calc(13px * var(--text-scale));
}

/* ============================================================
   Sheet — the one sanctioned pattern for secondary screens
   ============================================================ */
.sheet-backdrop {
  position: fixed;
  inset: 0;
  background: var(--scrim);
  z-index: 40;
}
.sheet {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  max-height: 82%;
  background: var(--card);
  border-radius: 26px 26px 0 0;
  z-index: 41;
  display: flex;
  flex-direction: column;
  padding-bottom: calc(20px + env(safe-area-inset-bottom));
}
.sheet-handle {
  width: 36px;
  height: 4px;
  border-radius: 2px;
  background: var(--t4);
  margin: 10px auto 0;
  flex: none;
}
.sheet-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px var(--margin) 4px;
  flex: none;
}
.sheet-close {
  width: 30px;
  height: 30px;
  border-radius: 15px;
  background: var(--card-hi);
  display: grid;
  place-items: center;
}
.sheet-body {
  padding: 14px var(--margin) 4px;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}
.sheet-empty {
  color: var(--t3);
  padding: 24px 0;
  text-align: center;
}

/* ============================================================
   Today — add dose / history / empty state
   ============================================================ */
.empty-state {
  color: var(--t3);
  padding: 18px 4px;
}
.add-dose {
  flex: none;
  margin-top: 12px;
  height: 56px;
  min-height: 56px;
  width: 100%;
  border-radius: 16px;
  box-shadow: inset 0 0 0 1.5px var(--purple);
  color: var(--purple);
  font-size: calc(15px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.1px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
}
.action-row {
  display: flex;
  gap: 10px;
}
.action-row .add-dose {
  flex: 1;
  min-width: 0;
}
.history-summary {
  color: var(--t2);
  margin-bottom: 12px;
}
.schedule-remove-btn {
  flex: none;
  width: 100%;
  height: 52px;
  min-height: 52px;
  border-radius: 16px;
  box-shadow: inset 0 0 0 1.5px var(--danger-dim);
  color: var(--danger);
  font-size: calc(15px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.1px;
  margin-bottom: 16px;
}
.history-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.history-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--card-hi);
  border-radius: 15px;
  padding: 10px 14px;
}
.history-meta {
  color: var(--t3);
  margin-top: 2px;
}

/* ============================================================
   Discover — glossary detail sheet
   ============================================================ */
.glossary-tags {
  display: flex;
  gap: 8px;
  margin-bottom: 4px;
}
.tag {
  padding: 5px 10px;
  border-radius: 10px;
  background: var(--card-hi);
  color: var(--t2);
  font-size: calc(12px * var(--text-scale));
  font-weight: 600;
}
.glossary-field {
  margin-top: 16px;
}
.research-link {
  display: flex;
  align-items: center;
  min-height: 44px;
  padding: 11px 0;
  box-shadow: inset 0 1.5px 0 var(--card-hi);
  color: var(--t1);
}
.research-link:first-child {
  box-shadow: none;
}

/* ============================================================
   My Stack
   ============================================================ */
.stack-list {
  margin-top: 13px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.stack-row {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--card);
  border-radius: 16px;
  min-height: 56px;
  padding: 10px 12px;
}
.stack-row-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.stack-vial {
  color: var(--purple);
}
.stack-name {
  font-size: calc(15px * var(--text-scale));
  font-weight: 600;
  letter-spacing: -0.1px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.stack-meta {
  color: var(--t3);
}
.expiry-badge.soon {
  color: var(--purple);
}
.expiry-badge.expired {
  color: #ff6b6b;
}
.stack-expiry-btn {
  flex: none;
  display: inline-flex;
  align-items: center;
  height: 32px;
  padding: 0 10px;
  border-radius: 10px;
  background: var(--card-hi);
  color: var(--t2);
  font-weight: 600;
  font-size: calc(12px * var(--text-scale));
}
.stack-remove {
  flex: none;
  width: 34px;
  height: 34px;
  border-radius: 17px;
  background: var(--card-hi);
  display: grid;
  place-items: center;
}

/* ============================================================
   Progress notes
   ============================================================ */
.progress-list {
  margin-top: 13px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.progress-row {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--card);
  border-radius: 16px;
  padding: 10px 12px;
}
.progress-row-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.note-thumb {
  flex: none;
  width: 44px;
  height: 44px;
  border-radius: 10px;
  background: var(--card-hi);
  object-fit: cover;
}
.note-thumb-empty {
  display: grid;
  place-items: center;
}
.field-file {
  color: var(--t2);
  font-size: calc(13px * var(--text-scale));
}

/* ============================================================
   Reconstitution calculator
   ============================================================ */
.recon-input-row {
  display: flex;
  align-items: center;
  gap: 10px;
}
.recon-input-row .field-input {
  flex: 1;
}
.recon-unit {
  flex: none;
  color: var(--t3);
  font-size: calc(14px * var(--text-scale));
  font-weight: 600;
  width: 34px;
}
.recon-unit-toggle {
  flex: none;
  display: flex;
  background: var(--card);
  border-radius: 12px;
  padding: 3px;
  gap: 3px;
}
.recon-unit-btn {
  display: inline-flex;
  align-items: center;
  height: 36px;
  padding: 0 16px;
  border-radius: 12px;
  color: var(--t3);
  font-size: calc(13px * var(--text-scale));
  font-weight: 600;
}
.recon-unit-btn.active {
  background: var(--purple);
  color: var(--bg);
}
.recon-result {
  margin-top: 20px;
  background: var(--card);
  border-radius: 16px;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.recon-result-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.recon-big {
  font-size: calc(20px * var(--text-scale));
  font-weight: 700;
  color: var(--purple);
  letter-spacing: -0.02em;
}

/* ============================================================
   Injection site body map
   ============================================================ */
.bodymap-card {
  margin-top: 13px;
  background: var(--card);
  border-radius: 18px;
  padding: 18px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}
.bodymap-figure {
  width: 128px;
  height: 208px;
}
.bodymap-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
}
.bodymap-chip {
  display: inline-flex;
  align-items: center;
  height: 36px;
  padding: 0 14px;
  border-radius: 12px;
  background: var(--card-hi);
  color: var(--t2);
  font-size: calc(12px * var(--text-scale));
  font-weight: 600;
}
.bodymap-chip.active {
  background: var(--purple);
  color: var(--bg);
}
.bodymap-detail {
  color: var(--t2);
  text-align: center;
}
.bodymap-detail strong {
  color: var(--t1);
  font-weight: 600;
}


/* ============================================================
   Setup screen — shown when the Supabase env vars are absent.
   Deliberately plain: it is a diagnostic, not part of the product.
   ============================================================ */
.setup {
  height: 100dvh;
  overflow-y: auto;
  background: var(--bg);
  padding: calc(env(safe-area-inset-top) + 32px) var(--margin) 40px;
}
.setup-inner {
  max-width: 420px;
  margin: 0 auto;
}
.setup-title {
  font-size: 27px;
  font-weight: 700;
  letter-spacing: -0.7px;
  line-height: 32px;
}
.setup-body {
  margin-top: 10px;
  color: var(--t2);
  font-size: 15px;
  line-height: 21px;
}
.setup-vars {
  margin-top: 20px;
  border-radius: 16px;
  background: var(--card);
  padding: 4px 14px;
}
.setup-var {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 40px;
  font-size: 13px;
}
.setup-var code {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
}
.setup-state {
  color: var(--t3);
  font-size: 12px;
}
.setup-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex: none;
}
.setup-dot.on {
  background: var(--purple);
}
.setup-dot.off {
  background: var(--t4);
}
.setup-steps {
  margin: 22px 0 0;
  padding-left: 20px;
  color: var(--t2);
  font-size: 14px;
  line-height: 21px;
}
.setup-steps li {
  margin-bottom: 12px;
}
.setup-steps b {
  color: var(--t1);
  font-weight: 600;
}
.setup-steps code {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12.5px;
  color: var(--t1);
}

/* the form saying where a pre-filled value came from — it is always the
   user's own prior entry, never anything the app decided */
.prefill-note {
  margin-top: -6px;
  color: var(--t3);
  line-height: 16px;
}

/* the taken segment wipes on from the left — ease-in, so it starts slow */
.arc-fill {
  transition: stroke-dashoffset 620ms cubic-bezier(0.42, 0, 1, 1);
}
@media (prefers-reduced-motion: reduce) {
  .arc-fill {
    transition: none;  
  }
}

/* the preview box holds the first paper on file rather than a placeholder */
.thumb-paper {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 7px;
  padding: 20px 20px 18px;
  text-align: left;
  text-decoration: none;
  color: var(--t1);
}
.thumb-kicker {
  color: var(--t3);
}
.thumb-title {
  font-size: 19px;
  font-weight: 600;
  letter-spacing: -0.3px;
  line-height: 25px;
  /* long paper titles are normal; clamp rather than blow the box open */
  display: -webkit-box;
  -webkit-line-clamp: 5;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.thumb-meta {
  color: var(--t2);
}
.thumb-cta {
  margin-top: auto;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--purple);
}

.result-kind {
  margin-top: 3px;
  color: var(--t3);
  text-transform: capitalize;
}

/* branded product header inside the detail sheet */
.glossary-brand {
  display: flex;
  align-items: baseline;
  gap: 4px;
  margin-bottom: 12px;
  color: var(--t3);
}
.glossary-brand-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--t2);
}
.glossary-brand-link {
  margin-left: auto;
  color: var(--purple);
  text-decoration: none;
  min-height: 32px;
  display: inline-flex;
  align-items: center;
}

/* ============================================================
   Discover tabs — segmented control over a swipeable pager
   ============================================================ */
.tabs {
  position: relative;
  margin-top: 18px;
  /* The track is three panels wide and was spilling past the panel's content
     box, so slivers of the neighbouring tabs showed down both edges. `clip`
     rather than `hidden`: hidden would make this a scroll container and break
     the sticky chat composer inside it. */
  overflow-x: clip;
}
.tabs-bar {
  position: relative;
  display: flex;
  gap: 22px;
  padding-bottom: 11px;
}
.tabs-tab {
  flex: none;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.2px;
  color: var(--t2);
  min-height: 34px;
  transition: color 180ms ease-out;
}
.tabs-tab.on {
  color: var(--t1);
}
.tabs-underline {
  position: absolute;
  left: 0;
  bottom: 0;
  height: 2px;
  border-radius: 1px;
  background: var(--purple);
  will-change: transform, width;
}
.tabs-track {
  display: flex;
  margin-top: 4px;
  will-change: transform;
}
.tabs-panel {
  flex: none;
  min-width: 0;
  /* the pager only translates; each panel scrolls with the page */
  padding-right: 0;
}
/* the peptide tab's standing caveat */
.tab-note {
  margin: 14px 0 2px;
  color: var(--t3);
  line-height: 1.45;
}
.evidence-chip {
  display: inline-flex;
  align-items: center;
  height: 22px;
  padding: 0 9px;
  border-radius: 999px;
  box-shadow: inset 0 0 0 1px var(--purple-dim);
  color: var(--purple);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.2px;
  text-transform: capitalize;
  flex: none;
}

/* ============================================================
   Discover — a flush list against a rail. A row only becomes a
   card once it is opened.
   ============================================================ */
.prod-list {
  position: relative;
  margin-top: 16px;
  padding-left: 22px;
}
/* the same white rail the paper list used */
.prod-list .rail {
  position: absolute;
  left: 3px;
  top: 6px;
  bottom: 6px;
  width: 2px;
  border-radius: 1px;
  background: var(--t1);
}
.prod {
  border-radius: 18px;
  background: none;
  transition:
    background-color 200ms ease-out,
    padding 200ms ease-out,
    margin 200ms ease-out;
}
/* only the open one is a card */
.prod.open {
  background: var(--card);
  margin: 10px -12px;
  padding: 2px 12px 12px;
}
.prod-row {
  width: 100%;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 13px 0;
  text-align: left;
}
.prod-main {
  flex: 1;
  min-width: 0;
}
.prod-name {
  display: block;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.2px;
  line-height: 21px;
}
.prod-pills {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}
.prod-chev {
  flex: none;
  display: flex;
  margin-top: 4px;
  transition: transform 200ms ease-out;
}
.prod-chev.open {
  transform: rotate(180deg);
}

/* ── the pills ──
   NOT `.pill`: the tab bar's travelling indicator already owns that class and
   is position:absolute, which took these out of flow and stacked every one of
   them at the same coordinates off the left edge. */
.tagpill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 24px;
  padding: 0 9px 0 7px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: -0.05px;
  white-space: nowrap;
  flex: none;
  background: var(--card);
  color: var(--t2);
}
.tagpill-icon {
  display: flex;
  opacity: 0.85;
}
.tagpill-accent {
  background: var(--purple-dim);
  color: var(--t1);
}
.tagpill-strong {
  background: var(--purple-dim);
  color: var(--t1);
}
.tagpill-mixed {
  background: var(--card-hi);
  color: var(--t2);
}
.tagpill-thin {
  background: var(--card);
  color: var(--t3);
}
/* inside an open card the row background is --card, so the pills need to lift */
.prod.open .tagpill {
  background: var(--card-hi);
}
.prod.open .tagpill-accent,
.prod.open .tagpill-strong {
  background: var(--purple-dim);
}

/* ── the opened card ── */
.prod-card {
  padding: 2px 0 4px;
  animation: prod-open 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
@keyframes prod-open {
  from { opacity: 0; transform: translateY(-6px); }
  to { opacity: 1; transform: translateY(0); }
}
.prod-evidence {
  margin-bottom: 12px;
  color: var(--t2);
  line-height: 1.5;
}
.prod-evidence b {
  color: var(--t1);
  font-weight: 600;
}
.prod-preview {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 14px 15px;
  border-radius: 16px;
  background: var(--bg);
  color: var(--t1);
  text-decoration: none;
}
.prod-preview-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--t3);
}
.prod-preview-year {
  margin-left: auto;
  font-weight: 600;
}
.prod-preview-title {
  font-size: 15px;
  font-weight: 600;
  line-height: 20px;
  letter-spacing: -0.1px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.prod-preview-cta {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-top: 2px;
  color: var(--purple);
}
.prod-preview-empty {
  padding: 12px 2px;
  color: var(--t3);
}
/* ── the one question asked on a card ──
   Iron is the only figure that turns on menstrual status, so it is asked here
   rather than in onboarding, where it would be put to everyone for the sake
   of one entry. Same radius and inset as .prod-preview above it. */
.prod-ask {
  margin-top: 14px;
  padding: 14px 15px;
  border-radius: 16px;
  background: var(--bg);
}
.prod-ask-target {
  color: var(--t1);
  line-height: 1.5;
}
.prod-ask-q {
  display: block;
  margin-top: 12px;
  color: var(--t3);
}
.prod-ask-opts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 8px;
}
.prod-ask-opt {
  min-height: 44px;
  padding: 0 14px;
  border-radius: 14px;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.1px;
  background: var(--card);
  color: var(--t2);
}
.prod-ask-opt.on {
  background: var(--purple-dim);
  color: var(--t1);
  box-shadow: inset 0 0 0 1.5px var(--purple);
}
.prod-ask-why {
  margin-top: 10px;
  color: var(--t3);
  line-height: 1.5;
}

.prod-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
}
.prod-btn {
  flex: 1;
  min-width: 140px;
  min-height: 46px;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.1px;
  box-shadow: inset 0 0 0 1.5px var(--purple);
  color: var(--purple);
}
.prod-btn.fill {
  background: var(--purple);
  color: var(--bg);
  box-shadow: none;
}
.prod-btn.fill:disabled {
  opacity: 0.65;
}
.prod-btn.wide {
  flex-basis: 100%;
}

/* ============================================================
   Ask AI
   ============================================================ */
.ask {
  display: flex;
  flex-direction: column;
  min-height: 62vh;
}
.ask-thread {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-top: 8px;
}
.ask-empty {
  text-align: center;
  padding: 30px 0 10px;
}
.ask-mark {
  display: inline-grid;
  place-items: center;
  width: 76px;
  height: 76px;
  border-radius: 24px;
  background: var(--card);
}
.ask-empty-line {
  margin: 16px auto 0;
  max-width: 260px;
  font-size: 16px;
  color: var(--t2);
  line-height: 1.5;
}
.ask-examples {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 22px;
}
.ask-example {
  min-height: 46px;
  padding: 12px 16px;
  border-radius: 16px;
  background: var(--card);
  color: var(--t2);
  font-size: 14px;
  text-align: left;
}
.ask-bubble {
  max-width: calc(100% - 60px);
  padding: 12px 15px;
  border-radius: 20px;
  font-size: 15px;
  line-height: 21px;
  letter-spacing: -0.1px;
  white-space: pre-wrap;
}
.ask-bubble.user {
  align-self: flex-end;
  background: var(--purple);
  color: #fff;
}
.ask-bubble.assistant {
  align-self: flex-start;
  background: var(--card);
  color: var(--t1);
}
.ask-dots {
  display: inline-flex;
  gap: 5px;
  padding: 3px 0;
}
.ask-dots i {
  width: 6px;
  height: 6px;
  border-radius: 3px;
  background: var(--t3);
  animation: ask-pulse 1.2s ease-in-out infinite;
}
.ask-dots i:nth-child(2) { animation-delay: 0.15s; }
.ask-dots i:nth-child(3) { animation-delay: 0.3s; }
@keyframes ask-pulse {
  0%, 60%, 100% { opacity: 0.3; }
  30% { opacity: 1; }
}
.ask-composer {
  position: sticky;
  bottom: 0;
  padding: 12px 0 4px;
  background: var(--bg);
}
.ask-input-row {
  display: flex;
  align-items: flex-end;
  gap: 8px;
}
.ask-input {
  flex: 1;
  min-width: 0;
  min-height: 48px;
  max-height: 132px;
  padding: 13px 16px;
  border-radius: 20px;
  border: 0;
  outline: none;
  resize: none;
  background: var(--card);
  color: var(--t1);
  font: inherit;
  font-size: 15px;
  line-height: 21px;
}
.ask-input::placeholder {
  color: var(--t3);
}
.ask-send {
  flex: none;
  width: 44px;
  height: 44px;
  border-radius: 22px;
  display: grid;
  place-items: center;
  background: var(--card);
  color: var(--t3);
  transition: background-color 180ms ease-out, color 180ms ease-out;
}
.ask-send.on {
  background: var(--purple);
  color: var(--bg);
}
.ask-disclaimer {
  margin-top: 8px;
  text-align: center;
  color: var(--t3);
}
@media (prefers-reduced-motion: reduce) {
  .prod-card { animation: none; }
  .ask-dots i { animation: none; opacity: 0.6; }
}

import { expect, seedSignedIn, test } from './support/app';
import { STUB_USER_ID } from './support/catalogue';

/** TEMPORARY measurement harness — delete before committing. */

const WIDTHS = [375, 390, 430];

function items(times: string[]) {
  return times.map((t, i) => ({
    id: `dddddddd-0000-4000-8000-00000000000${i + 1}`,
    user_id: STUB_USER_ID,
    glossary_id: 'aaaaaaaa-0000-4000-8000-000000000001',
    name: `Scratch ${i + 1}`,
    amount: '1 capsule',
    scheduled_time: t,
    injection_site: null,
    active: true,
    created_at: '2020-01-01T00:00:00.000Z',
    start_date: '2020-01-01',
  }));
}

for (const width of WIDTHS) {
  test.describe(`w${width}`, () => {
    test.use({ viewport: { width, height: 852 } });

    test(`measures the arc at ${width}`, async ({ page, app }) => {
      await seedSignedIn(page, app.stub);
      app.stub.db.profiles[0].sleep_time = '00:30:00';
      app.stub.db.schedule_items.push(...items(['06:00:00', '08:00:00', '12:00:00', '18:00:00', '22:00:00', '23:30:00']));
      await page.goto('/');
      await expect(page.getByRole('heading', { name: 'Today' })).toBeVisible();
      await expect(page.locator('.arc-wrap svg path')).not.toHaveCount(0);

      const m = await page.evaluate(() => {
        const svg = document.querySelector('.arc-wrap svg') as SVGSVGElement;
        const panel = svg.closest('.panel') as HTMLElement;
        const paths = [...svg.querySelectorAll('path')];
        const boxes = paths.map((p) => {
          const r = p.getBoundingClientRect();
          return { l: +r.left.toFixed(2), r: +r.right.toFixed(2), t: +r.top.toFixed(2), b: +r.bottom.toFixed(2) };
        });
        const svgR = svg.getBoundingClientRect();
        const panelR = panel.getBoundingClientRect();
        return {
          viewBox: svg.getAttribute('viewBox'),
          attrW: svg.getAttribute('width'),
          attrH: svg.getAttribute('height'),
          svg: { l: +svgR.left.toFixed(2), r: +svgR.right.toFixed(2), t: +svgR.top.toFixed(2), b: +svgR.bottom.toFixed(2) },
          panel: { l: +panelR.left.toFixed(2), r: +panelR.right.toFixed(2) },
          paint: {
            l: +Math.min(...boxes.map((b) => b.l)).toFixed(2),
            r: +Math.max(...boxes.map((b) => b.r)).toFixed(2),
            t: +Math.min(...boxes.map((b) => b.t)).toFixed(2),
            b: +Math.max(...boxes.map((b) => b.b)).toFixed(2),
          },
        };
      });
      console.log(`\n=== ${width} ===\n` + JSON.stringify(m, null, 2));
      await page.locator('.arc-wrap').screenshot({ path: `.scratch/arc-${width}.png` });
      await page.screenshot({ path: `.scratch/today-${width}.png` });
    });
  });
}

