import { expect, seedSignedIn, test } from './support/app';
import { STUB_USER_ID } from './support/catalogue';

/** TEMPORARY measurement harness — delete before committing. */

const WIDTHS = [375, 390, 430];
const TIMES = ['08:00:00', '13:00:00', '18:00:00', '20:00:00', '21:30:00', '22:00:00'];

function items(times: string[]) {
  return times.map((t, i) => ({
    id: `dddddddd-0000-4000-8000-00000000000${i + 1}`,
    user_id: STUB_USER_ID,
    glossary_id: 'aaaaaaaa-0000-4000-8000-000000000001',
    name: `Scratch ${i + 1}`,
    amount: '1 capsule',
    scheduled_time: t,
    injection_site: null,
    active: true,
    created_at: '2020-01-01T00:00:00.000Z',
    start_date: '2020-01-01',
  }));
}

for (const width of WIDTHS) {
  test.describe(`w${width}`, () => {
    test.use({ viewport: { width, height: 852 }, deviceScaleFactor: 4 });

    for (const n of [1, 2, 3, 6]) {
      test(`arc at ${width} with ${n}`, async ({ page, app }) => {
        await seedSignedIn(page, app.stub);
        // the seeded item is one of the n
        app.stub.db.schedule_items.push(...items(TIMES.slice(0, n - 1)));
        await page.goto('/');
        await expect(page.getByRole('heading', { name: 'Today' })).toBeVisible();
        await expect(page.locator('.arc-wrap svg path')).not.toHaveCount(0);

        const m = await page.evaluate(() => {
          const svg = document.querySelector('.arc-wrap svg') as SVGSVGElement;
          const panel = svg.closest('.panel') as HTMLElement;
          const r = svg.getBoundingClientRect();
          const p = panel.getBoundingClientRect();
          const ends = (document.querySelector('.arc-ends') as HTMLElement).getBoundingClientRect();
          return {
            paths: svg.querySelectorAll('path').length / 2,
            svg: { l: +r.left.toFixed(2), r: +r.right.toFixed(2), t: +r.top.toFixed(2), b: +r.bottom.toFixed(2) },
            panel: { l: +p.left.toFixed(2), r: +p.right.toFixed(2), w: +p.width.toFixed(2) },
            labelTop: +ends.top.toFixed(2),
            labels: [...document.querySelectorAll('.arc-ends span')].map((s) => s.textContent),
            fits: r.left >= p.left && r.right <= p.right,
          };
        });
        console.log(`\n=== ${width} / ${n} === ` + JSON.stringify(m));
        await page.screenshot({
          path: `.scratch/end-left-${width}-${n}.png`,
          clip: { x: m.svg.l - 6, y: m.svg.t + 18, width: 44, height: m.svg.b - m.svg.t - 8 },
        });
        await page.screenshot({
          path: `.scratch/end-right-${width}-${n}.png`,
          clip: { x: m.svg.r - 38, y: m.svg.t + 18, width: 44, height: m.svg.b - m.svg.t - 8 },
        });
        await page.locator('.arc-wrap').screenshot({ path: `.scratch/arc-${width}-${n}.png` });
      });
    }
  });
}

