export interface ArcWindow {
  /** hours, the left-hand end of the arc */
  start: number;
  /** hours, the right-hand end. Past 24 when the day runs over midnight. */
  end: number;
  /** where a dose's clock time sits on that scale */
  at: (hour: number) => number;
}

/**
 * What the arc spans, which is the waking day plus anything outside it.
 *
 * Two things it will not do, because both draw a dose at a time it is not:
 *
 * - Clamp. A 6am dose for someone who wakes at 7 used to stack onto the left
 *   end, labelled 7am. The window widens to the dose instead.
 * - Read a bedtime past midnight as a bedtime before breakfast. `dayEnd` of
 *   00:30 is a smaller number than a `dayStart` of 07:00, which collapsed the
 *   span to nothing and drew every dose of the day as one segment. It means
 *   the day runs on into the next one, so the end moves to 24.5 and the doses
 *   before it move with it — but only those. Something taken at 6am is still
 *   the near end of the day, not the far end of it.
 */
export function windowFor(doses: ArcDose[], dayStart: number, dayEnd: number): ArcWindow {
  const wraps = dayEnd <= dayStart;
  const at = (hour: number) => (wraps && hour < dayEnd ? hour + 24 : hour);
  const hours = doses.map((d) => at(d.hour)).filter((h) => Number.isFinite(h));
  const start = Math.min(dayStart, ...hours);
  const end = Math.max(wraps ? dayEnd + 24 : dayEnd, ...hours);
  return { start, end: Math.max(end, start + 0.5), at };
}

