test('with no doses the arc is the waking day', () => {
  expect(windowFor([], 7, 23)).toMatchObject({ start: 7, end: 23 });
});

test('doses inside the waking day leave it alone', () => {
  expect(windowFor([dose(8), dose(13), dose(22)], 7, 23)).toMatchObject({ start: 7, end: 23 });
});

test('a dose before waking widens the start rather than stacking on it', () => {
  expect(windowFor([dose(6), dose(8)], 7, 23).start).toBe(6);
});

test('a dose after bedtime widens the end', () => {
  expect(windowFor([dose(8), dose(23.5)], 7, 23).end).toBe(23.5);
});

test('the widest dose wins at each end', () => {
  const w = windowFor([dose(5.5), dose(6), dose(23.5), dose(23.25)], 7, 23);
  expect(w).toMatchObject({ start: 5.5, end: 23.5 });
});

test('a bedtime past midnight runs the day on rather than collapsing it', () => {
  // 00:30 is a smaller number than 07:00. Read literally it is a span of
  // minus six and a half hours, which drew every dose of the day as one
  // segment at one time.
  const w = windowFor([dose(8), dose(23)], 7, 0.5);
  expect(w).toMatchObject({ start: 7, end: 24.5 });
});

test('a dose after midnight sits at the far end of a day that runs past it', () => {
  const w = windowFor([dose(8), dose(0.25)], 7, 0.5);
  expect(w.at(0.25)).toBe(24.25);
  expect(w).toMatchObject({ start: 7, end: 24.5 });
});

