  // 6am is before waking, not after bedtime — it widens the start. Lifting
  // every hour below dayStart would have thrown it to the right-hand end.
  const w = windowFor([dose(6), dose(23)], 7, 0.5);
  expect(w.at(6)).toBe(6);
  expect(w).toMatchObject({ start: 6, end: 24.5 });
});

test('a dose past a midnight bedtime widens the end past midnight', () => {
  expect(windowFor([dose(1)], 7, 0.5).end).toBe(25);
});

test('a bedtime of exactly midnight is the end of the day, not the start', () => {
  expect(windowFor([dose(20)], 7, 0)).toMatchObject({ start: 7, end: 24 });
});

