  // wake and sleep set to the same time; the span divides the sweep, so zero
  // is the one value it cannot take.
  expect(windowFor([], 9, 9).end).toBe(9.5);
});

test('an unparseable time cannot take the window with it', () => {
  const w = windowFor([dose(NaN), dose(9)], 7, 23);
  expect(w).toMatchObject({ start: 7, end: 23 });
});

